static Project crossfadeFixture(){auto p=emptyProject();p.bpm=120;p.songMode=true;p.loop=false;p.clips.clear();Clip first;first.track=0;first.audioPath="crossfade-source.wav";first.beat=0;first.length=4;first.sourceOffset=.2;first.gain=.6f;first.fadeIn=.25;auto second=first;second.editorId=Uuid().toString();second.beat=3;second.length=4;second.sourceOffset=.5;second.fadeIn=0;second.fadeOut=.5;p.clips={first,second};return p;}
static void testAudioCrossfades(const File& root,Assets& assets){
    auto source=crossfadeFixture();auto original=JSON::toString(projectToJson(source));Project out;AudioCrossfadeStats stats;expect(crossfadeSelectedAudio(source,{0,1},false,out,&stats).wasOk()&&stats.pairs.size()==1&&stats.changed==std::set<int>({0,1})&&out.clips[0].fadeOut==1&&out.clips[1].fadeIn==1,"crossfade fits outgoing and incoming linear fades to exact overlap");expect(out.clips[0].fadeIn==.25&&out.clips[1].fadeOut==.5&&out.clips[0].sourceOffset==.2&&out.clips[1].sourceOffset==.5&&out.clips[0].gain==.6f&&out.clips[1].beat==3&&out.clips[0].editorId==source.clips[0].editorId&&JSON::toString(projectToJson(source))==original,"crossfades preserve outer fades source offsets gain placement identities and source project");
    auto fitted=out;expect(crossfadeSelectedAudio(fitted,{0,1},false,out,&stats).wasOk()&&stats.changed.empty(),"already fitted crossfades report a no-op");expect(crossfadeSelectedAudio(fitted,{0,1},true,out,&stats).wasOk()&&out.clips[0].fadeIn==0&&out.clips[0].fadeOut==0&&out.clips[1].fadeOut==0&&stats.changed.size()==2,"clear fades removes both ends only from selected audio");expect(crossfadeSelectedAudio(source,{1},true,out,&stats).wasOk()&&out.clips[0].fadeIn==.25&&out.clips[1].fadeOut==0,"clear supports one clip and preserves unselected fades");
    auto chain=source;auto third=chain.clips[1];third.editorId=Uuid().toString();third.beat=6;chain.clips.push_back(third);expect(crossfadeSelectedAudio(chain,{0,1,2},false,out,&stats).wasOk()&&stats.pairs.size()==2&&out.clips[1].fadeIn==1&&out.clips[1].fadeOut==1,"crossfade handles a sequential three-clip chain as one operation");
    auto lanes=source;for(int i=0;i<2;++i){auto copy=source.clips[(size_t)i];copy.track=2;lanes.clips.push_back(copy);}expect(crossfadeSelectedAudio(lanes,{0,1,2,3},false,out,&stats).wasOk()&&stats.pairs.size()==2,"multiple lane transitions are fitted together");
    Project sentinel=emptyProject();sentinel.title="Preserved";auto token=JSON::toString(projectToJson(sentinel));auto reject=[&](const Project& p,const std::set<int>& selected,bool clear=false){return crossfadeSelectedAudio(p,selected,clear,sentinel).failed()&&JSON::toString(projectToJson(sentinel))==token;};expect(reject(source,{})&&reject(source,{-1,1})&&reject(source,{0,2})&&reject(source,{0}),"empty invalid and insufficient selections reject atomically");auto mixed=source;mixed.clips.push_back({1,0,0,4});expect(reject(mixed,{0,2})&&reject(mixed,{2},true),"pattern clips cannot receive audio fades or be silently skipped");auto touching=source;touching.clips[1].beat=4;expect(reject(touching,{0,1}),"edge-touching audio is not an existing overlap");auto separate=source;separate.clips[1].track=1;expect(reject(separate,{0,1}),"different lanes are not crossfade pairs");auto nested=source;nested.clips[1].beat=1;nested.clips[1].length=2;expect(reject(nested,{0,1}),"nested overlaps reject without choosing an arbitrary fade direction");nested=source;nested.clips[1].beat=0;expect(reject(nested,{0,1}),"identical starts reject ambiguous transitions");nested=source;nested.clips[1].length=1;expect(reject(nested,{0,1}),"identical ends reject ambiguous transitions");auto triple=chain;triple.clips[2].beat=3.5;expect(reject(triple,{0,1,2})&&reject(triple,{0,1}),"third audio in the transition rejects even when it is unselected");auto outer=source;outer.clips[0].fadeIn=3.5;expect(reject(outer,{0,1}),"conflicting outer fades reject instead of silently changing other ends");expect(crossfadeSelectedAudio(outer,{0,1},true,out).wasOk()&&crossfadeSelectedAudio(out,{0,1},false,sentinel).wasOk(),"clear fades can resolve a conflicting previous envelope");
    auto file=root.getChildFile("crossfade-render-source.wav");AudioBuffer<float> tone(2,120000);for(int i=0;i<120000;++i)for(int ch=0;ch<2;++ch)tone.setSample(ch,i,.2f);WavAudioFormat format;auto stream=file.createOutputStream();std::unique_ptr<AudioFormatWriter> writer(stream?format.createWriterFor(stream.get(),48000,2,24,{},0):nullptr);bool written=false;if(writer){stream.release();written=writer->writeFromAudioSampleBuffer(tone,0,120000);writer.reset();}expect(written,"create constant crossfade audio fixture");auto musical=emptyProject();musical.bpm=120;musical.songMode=true;musical.loop=false;musical.master=1;musical.tracks[0].volume=1;musical.tracks[0].send=0;Clip a;a.track=0;a.beat=0;a.length=2;a.audioPath=file.getFullPathName();auto b=a;b.beat=1;b.length=2;b.editorId=Uuid().toString();musical.clips={a,b};auto raw=render(musical,assets,root,96000,127);crossfadeSelectedAudio(musical,{0,1},false,out);auto cross=render(out,assets,root,96000,127);expect(raw.getMagnitude(0,30000,12000)>cross.getMagnitude(0,30000,12000)*1.9f,"actual render replaces doubled correlated overlap with a constant-sum transition");auto other=render(out,assets,root,96000,1024);bool exact=true;for(int ch=0;ch<2;++ch)for(int i=0;i<96000;++i)exact&=cross.getSample(ch,i)==other.getSample(ch,i);expect(exact,"crossfade rendering is sample-exact across callback block sizes");
    auto saved=root.getChildFile("audio-crossfades.pulse");Project loaded;expect(saveProject(out,saved).wasOk()&&loadProject(saved,loaded).wasOk()&&loaded.clips[0].fadeOut==1&&loaded.clips[1].fadeIn==1,"crossfades persist using schema16 fade fields");
}
